import sys, base64
sys.path.insert(0, '/workspace/submission'); sys.path.insert(0, '/workspace/deps')
from ledger import parse_record
from common import Invalid
import ipaddress
def low(n):
    net = ipaddress.IPv6Network('2001:db8:1:100::/56', strict=True)
    return str(ipaddress.IPv6Address(int(net.network_address) + n))
ctx = {'leases': {'L': {'id': 'L', 'start': 0, 'end': 100}}, 'services': {'W': 'tcp'}}
lookup = {('L', '0/i1'): (int(ipaddress.IPv6Address(low(1))), False)}
row = ['app', 'a', '0', '1', 'put', 'L', '1', '', low(1), '', 'open', 'W', '0',
       base64.b64encode(b'z' * 65536).decode()]
try:
    rec = parse_record(row, ctx, lookup)
    print('ok', len(rec['payload']))
except Invalid as e:
    print('rejected:', e)
print('b64 len', len(row[13]))
EOF
